import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"ReadValue","description":"","frontmatter":{},"headers":[],"relativePath":"components/read-value.md","filePath":"components/read-value.md"}'),r={name:"components/read-value.md"};function i(l,e,n,s,h,c){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="readvalue" tabindex="-1">ReadValue <a class="header-anchor" href="#readvalue" aria-label="Permalink to &quot;ReadValue&quot;">​</a></h1><p>ReadValue is a value that is read, not edited, in the place of a control.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it in a <a href="./field">Field</a> or a <a href="./pair">Pair</a> on a screen that is only viewed, or for a value that cannot be changed. Identifiers use <code>mono</code>; a value that is not set is a muted sentence.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td>required</td><td>The value</td></tr><tr><td><code>mono</code></td><td><code>false</code></td><td>The monospace font, with figures of equal width</td></tr><tr><td><code>muted</code></td><td><code>false</code></td><td>Not set, or left at the default</td></tr><tr><td><code>clamp</code></td><td><code>false</code></td><td>One line with an ellipsis</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It has no outline: it is body text, and the Field or the Pair around it holds the distances. Inside a control (a pair or a list item) it is trimmed to its ink; elsewhere it keeps its line box, trimmed only on the side that touches the edge of a container. With <code>clamp</code> the full text shows on hover and on keyboard focus when it is clipped.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/read-value/" title="ReadValue" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/read-value/" target="_blank" rel="noopener">ReadValue</a></figcaption></figure>',10)])])}const m=a(r,[["render",i]]);export{p as __pageData,m as default};
